class Solution {
    public TreeNode invertTree(TreeNode root) {
        if (root == null) return null;

        TreeNode tmp = root.left;
        root.left = invertTree(root.right);   // 翻好的右子树接到左边
        root.right = invertTree(tmp);         // 翻好的原左子树接到右边
        return root;
    }
}
